#include <algorithm>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <vector>
#include <deque>
using namespace std;
int main(int argc,char**argv){ifstream in(argv[1]);int p,n,N,F;in>>p>>n>>N>>F;vector<int>deg(N);vector<vector<int>>shift(n,vector<int>(N));for(int&i:deg)in>>i;for(auto&r:shift)for(int&i:r)in>>i;vector<vector<pair<int,int>>>base(N);deque<vector<pair<int,int>>>queue;for(int j=0;j<F;j++){int len;in>>len;vector<pair<int,int>>r(len);for(auto&[i,c]:r)in>>i>>c;queue.push_back(move(r));}vector<int>t(N);for(int&i:t)in>>i;auto power=[&](int a,int b){long long out=1;while(b){if(b&1)out=out*a%p;a=(long long)a*a%p;b>>=1;}return(int)out;};int rank=0,processed=0;auto reduce=[&](vector<int>&r){for(int i=0;i<N;i++)if(r[i]&&!base[i].empty()){int a=r[i];for(auto[k,c]:base[i]){r[k]=(r[k]-(long long)a*c)%p;if(r[k]<0)r[k]+=p;}}};while(!queue.empty()){auto src=move(queue.front());queue.pop_front();vector<int>r(N);for(auto[i,c]:src)r[i]=c;reduce(r);processed++;int pi=0;while(pi<N&&!r[pi])pi++;if(pi==N)continue;int iv=power(r[pi],p-2);vector<pair<int,int>>b;for(int i=pi;i<N;i++)if(r[i])b.emplace_back(i,(long long)r[i]*iv%p);base[pi]=b;rank++;for(int j=0;j<n;j++){vector<pair<int,int>>v;for(auto[k,c]:b)if(shift[j][k]>=0)v.emplace_back(shift[j][k],c);if(!v.empty())queue.push_back(move(v));}if(rank%250==0)cerr<<"rank "<<rank<<" queue "<<queue.size()<<" processed "<<processed<<"\n";}if(argc>2){ofstream out(argv[2]);out<<rank<<"\n";for(int i=0;i<N;i++)if(!base[i].empty()){vector<pair<int,int>>lo;for(auto[k,c]:base[i])if(deg[k]==deg[i])lo.emplace_back(k,c);out<<lo.size();for(auto[k,c]:lo)out<<" "<<k<<" "<<c;out<<"\n";}}reduce(t);cout<<"rank "<<rank<<" length "<<N-rank<<" processed "<<processed<<"\n";for(int d=1;d<=*max_element(deg.begin(),deg.end())+1;d++){int ct=0;for(int i=0;i<N;i++)if(deg[i]<d&&base[i].empty())ct++;cout<<"modm "<<d<<" length "<<ct<<"\n";}cout<<"t";for(int i=0;i<N;i++)if(t[i])cout<<" "<<i<<":"<<t[i];cout<<"\n";}
